package com.finanquest.sv.data.repository

import com.finanquest.sv.data.firebase.FirebaseProvider
import com.finanquest.sv.data.model.Categoria
import com.finanquest.sv.data.model.Presupuesto
import com.finanquest.sv.data.model.Movimiento
import com.google.firebase.firestore.ListenerRegistration
import com.finanquest.sv.utils.FinanzasIntegrante2

class PresupuestoRepository {
    private fun user()=FirebaseProvider.auth.currentUser?.uid?.let{FirebaseProvider.firestore.collection("usuarios").document(it)}
    fun escucharCategorias(cb:(List<Categoria>,String?)->Unit):ListenerRegistration? { val r=user()?.collection("categorias")?:run{cb(emptyList(),"Inicia sesión para consultar categorías");return null}; return r.addSnapshotListener{s,e->if(e!=null)cb(emptyList(),e.localizedMessage?:"No se pudieron cargar categorías") else cb(s?.documents.orEmpty().map{Categoria(it.id,it.getString("nombre")?:"",it.getDouble("limite")?:0.0,it.getDouble("umbral")?:.8,it.getBoolean("alertasActivas")?:true,it.getLong("creadaEn")?:0L)},null)} }
    fun guardarCategoria(nombre:String,limite:Double,umbral:Double,cb:(String?)->Unit){val r=user()?.collection("categorias")?:run{cb("Inicia sesión nuevamente");return};val id=nombre.trim().lowercase().replace(Regex("[^a-z0-9]+"),"_");r.document(id).set(mapOf("nombre" to nombre.trim(),"limite" to limite,"umbral" to umbral,"alertasActivas" to true,"creadaEn" to System.currentTimeMillis()),com.google.firebase.firestore.SetOptions.merge()).addOnSuccessListener{cb(null)}.addOnFailureListener{cb(it.localizedMessage?:"No se pudo guardar la categoría")}}
    fun actualizarAlertasCategoria(categoria:Categoria,activas:Boolean,umbral:Double,cb:(String?)->Unit){val r=user()?.collection("categorias")?.document(categoria.id)?:run{cb("Inicia sesión nuevamente");return};r.update(mapOf("alertasActivas" to activas,"umbral" to umbral)).addOnSuccessListener{cb(null)}.addOnFailureListener{cb(it.localizedMessage?:"No se pudieron actualizar las alertas")}}
    fun escucharPresupuestos(cb:(List<Presupuesto>,String?)->Unit):ListenerRegistration? { val r=user()?.collection("presupuestos")?:run{cb(emptyList(),"Inicia sesión nuevamente");return null};return r.addSnapshotListener{s,e->if(e!=null)cb(emptyList(),e.localizedMessage?:"No se pudieron cargar presupuestos")else cb(s?.documents.orEmpty().map{Presupuesto(it.id,it.getString("categoriaId")?:"",it.getString("categoria")?:"",it.getDouble("limite")?:0.0,it.getString("periodo")?:"Mensual",it.getLong("inicioPeriodo")?:0L,it.getDouble("alertaUmbral")?:.8,it.getBoolean("activo")?:true)},null)} }
    fun guardarPresupuesto(categoria:String,limite:Double,periodo:String,cb:(String?)->Unit){val u=user()?:run{cb("Inicia sesión nuevamente");return};val id=categoria.trim().lowercase().replace(Regex("[^a-z0-9]+"),"_");val inicio=FinanzasIntegrante2.inicioPeriodoPresupuesto(periodo);u.collection("presupuestos").document(id).set(mapOf("categoriaId" to id,"categoria" to categoria.trim(),"limite" to limite,"periodo" to periodo,"inicioPeriodo" to inicio,"alertaUmbral" to .8,"activo" to true),com.google.firebase.firestore.SetOptions.merge()).addOnSuccessListener{cb(null)}.addOnFailureListener{cb(it.localizedMessage?:"No se pudo guardar el presupuesto")}}
    fun escucharMovimientos(cb:(List<Movimiento>,String?)->Unit):ListenerRegistration?{val r=user()?.collection("movimientos")?:run{cb(emptyList(),"Inicia sesión nuevamente");return null};return r.addSnapshotListener{s,e->if(e!=null)cb(emptyList(),e.localizedMessage?:"No se pudieron cargar movimientos")else cb(s?.documents.orEmpty().map{Movimiento(it.id,it.getString("cuentaId")?:"",it.getString("tipo")?:"Gasto",it.getDouble("monto")?:0.0,it.getString("categoria")?:"",it.getLong("fecha")?:0L,it.getString("nota")?:"")},null)}}
}
